def sort_numbers(numbers: str) -> str:
    words_to_numbers = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }

    numbers_list = numbers.split()
    numerical_values = [words_to_numbers[word] for word in numbers_list]
    sorted_numerical_values = sorted(numerical_values)
    sorted_words = [key for value, key in sorted(zip(sorted_numerical_values, numbers_list))]

    return ' '.join(sorted_words)
from typing import List

def sort_numbers(numbers: str) -> str:
    words_to_nums = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    nums_to_words = {v: k for k, v in words_to_nums.items()}

    num_list = numbers.split()
    num_list.sort(key=lambda x: words_to_nums[x])

    sorted_words = [nums_to_words[int(num)] for num in num_list]

    return ' '.join(sorted_words)
